INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('952491c7-1f18-4cb9-a991-182b60f4e4f1', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What happens when a BGP route has multiple paths with the same LOCAL_PREF?', '[{"id": "A", "text": "The shortest AS_PATH wins", "is_correct": true}, {"id": "B", "text": "The lowest MED wins", "is_correct": false}, {"id": "C", "text": "The oldest route wins", "is_correct": false}, {"id": "D", "text": "EBGP over IBGP", "is_correct": false}]', 'After LOCAL_PREF, BGP compares AS_PATH length (shorter is better). Then it checks origin type, MED, EBGP vs IBGP, and IGP metric.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '{"ru": "Что происходит, когда BGP-маршрут имеет несколько путей с одинаковым LOCAL_PREF?"}', '{"ru": [{"id": "A", "text": "The shortest AS_PATH wins"}, {"id": "B", "text": "The lowest MED wins"}, {"id": "C", "text": "The oldest route wins"}, {"id": "D", "text": "EBGP over IBGP"}]}', 'bdf3e2cdb038c640_gen_v2', true) ON CONFLICT (id) DO NOTHING;
