INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('e735defe-7eed-414d-9650-cf072e21a1e2', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command shows BGP routes in the routing table of a Junos device (variant 2).', '[{"id": "A", "text": "show route protocol bgp", "is_correct": true}, {"id": "B", "text": "show bgp routes", "is_correct": false}, {"id": "C", "text": "show route bgp", "is_correct": false}, {"id": "D", "text": "show protocols bgp routes", "is_correct": false}]', '''show route protocol bgp'' displays BGP routes in the routing table. ''show bgp summary'' shows BGP peering status (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Operations', 8.0, '{"ru": "Какая команда показывает BGP-маршруты в таблице маршрутизации Junos (вариант 2)."}', '{"ru": [{"id": "A", "text": "show route protocol bgp"}, {"id": "B", "text": "show bgp routes"}, {"id": "C", "text": "show route bgp"}, {"id": "D", "text": "show protocols bgp routes"}]}', '268546edaf16d013_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('9702aa0d-0475-4c97-be08-e6eac3ec4192', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of the ''load-balance'' per-packet action in Junos (variant 2).', '[{"id": "A", "text": "Distribute traffic across multiple equal-cost paths", "is_correct": true}, {"id": "B", "text": "Distribute traffic based on source IP", "is_correct": false}, {"id": "C", "text": "Create a static route for load sharing", "is_correct": false}, {"id": "D", "text": "Enable per-flow load balancing", "is_correct": false}]', '''load-balance per-packet'' enables per-packet load balancing across equal-cost multipath (ECMP) routes in the forwarding table (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '{"ru": "Какова цель action ''load-balance per-packet'' в Junos (вариант 2)."}', '{"ru": [{"id": "A", "text": "Distribute traffic across multiple equal-cost paths"}, {"id": "B", "text": "Distribute traffic based on source IP"}, {"id": "C", "text": "Create a static route for load sharing"}, {"id": "D", "text": "Enable per-flow load balancing"}]}', '101ae2ceea168b82_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('a7393214-0979-4370-a6df-ba8d16c68671', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which IS-IS level supports intra-area routing in Junos OS (variant 3).', '[{"id": "A", "text": "Level 1", "is_correct": true}, {"id": "B", "text": "Level 2", "is_correct": false}, {"id": "C", "text": "Level 1 and Level 2", "is_correct": false}, {"id": "D", "text": "Level 0", "is_correct": false}]', 'IS-IS Level 1 handles intra-area (within area) routing. Level 2 handles inter-area routing between different areas (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/is-is/"}', 'IS-IS', 12.0, '{"ru": "Какой уровень IS-IS поддерживает маршрутизацию внутри зоны в Junos OS (вариант 3)."}', '{"ru": [{"id": "A", "text": "Level 1"}, {"id": "B", "text": "Level 2"}, {"id": "C", "text": "Level 1 and Level 2"}, {"id": "D", "text": "Level 0"}]}', '42047c20699a515a_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('3e278f8b-ef28-4edc-9ec7-950236a956ca', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast network in Junos OS (variant 3).', '[{"id": "A", "text": "10 seconds", "is_correct": true}, {"id": "B", "text": "30 seconds", "is_correct": false}, {"id": "C", "text": "40 seconds", "is_correct": false}, {"id": "D", "text": "5 seconds", "is_correct": false}]', 'OSPF hello interval defaults to 10 seconds on broadcast and point-to-point networks, and 30 seconds on NBMA networks (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF', 12.0, '{"ru": "Каков интервал Hello по умолчанию для OSPF на широковещательной сети в Junos OS (вариант 3)."}', '{"ru": [{"id": "A", "text": "10 seconds"}, {"id": "B", "text": "30 seconds"}, {"id": "C", "text": "40 seconds"}, {"id": "D", "text": "5 seconds"}]}', '95763a68def76ad3_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('0ee8c0f8-6afd-4400-a021-af8c23ed3fd9', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which BGP attribute is used for loop prevention within an AS (variant 3).', '[{"id": "A", "text": "AS_PATH", "is_correct": true}, {"id": "B", "text": "NEXT_HOP", "is_correct": false}, {"id": "C", "text": "LOCAL_PREF", "is_correct": false}, {"id": "D", "text": "MED", "is_correct": false}]', 'AS_PATH is the primary loop prevention mechanism in BGP. When a router sees its own AS in the AS_PATH, it rejects the route (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP', 14.0, '{"ru": "Какой атрибут BGP используется для предотвращения петель внутри AS (вариант 3)."}', '{"ru": [{"id": "A", "text": "AS_PATH"}, {"id": "B", "text": "NEXT_HOP"}, {"id": "C", "text": "LOCAL_PREF"}, {"id": "D", "text": "MED"}]}', '9f21728706cb657b_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('ccea33ca-af22-4fc6-90fa-4e1c8b9aea70', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'Which command displays OSPF neighbor information on Junos (variant 3).', '[{"id": "A", "text": "show ospf neighbor", "is_correct": true}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show ospf database", "is_correct": false}, {"id": "D", "text": "show protocols ospf neighbor", "is_correct": false}]', '''show ospf neighbor'' displays OSPF adjacency states, neighbor IDs, and interface information (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF', 10.0, '{"ru": "Какая команда отображает информацию о OSPF-соседях в Junos (вариант 3)."}', '{"ru": [{"id": "A", "text": "show ospf neighbor"}, {"id": "B", "text": "show ospf interface"}, {"id": "C", "text": "show ospf database"}, {"id": "D", "text": "show protocols ospf neighbor"}]}', 'ee74ff9de0d39e3d_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('026a396b-3554-40b4-92a3-7437e83d2453', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In Junos, which policy action is used to reject a route (variant 3).', '[{"id": "A", "text": "reject", "is_correct": true}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "discard", "is_correct": false}, {"id": "D", "text": "drop", "is_correct": false}]', 'The ''reject'' action in a routing policy term rejects the route. In Junos, ''then reject'' is used in policy-options (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '{"ru": "Какое action политики в Junos используется для отклонения маршрута (вариант 3)."}', '{"ru": [{"id": "A", "text": "reject"}, {"id": "B", "text": "deny"}, {"id": "C", "text": "discard"}, {"id": "D", "text": "drop"}]}', '154080e79be58df7_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('5f86da9a-ffa6-45d1-9359-466aec20cd72', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default preference for OSPF external routes in Junos (variant 3).', '[{"id": "A", "text": "150", "is_correct": true}, {"id": "B", "text": "10", "is_correct": false}, {"id": "C", "text": "170", "is_correct": false}, {"id": "D", "text": "120", "is_correct": false}]', 'OSPF external routes (Type 5) have a default preference of 150 in Junos. OSPF internal routes have preference 10 (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 10.0, '{"ru": "Какое preference по умолчанию у внешних маршрутов OSPF в Junos (вариант 3)."}', '{"ru": [{"id": "A", "text": "150"}, {"id": "B", "text": "10"}, {"id": "C", "text": "170"}, {"id": "D", "text": "120"}]}', 'b079454301feba1f_gen_v2', true) ON CONFLICT (id) DO NOTHING;
