INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('f13fed9e-eed3-4674-8072-1446395f714c', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command shows BGP routes in the routing table of a Junos device (variant 3).', '[{"id": "A", "text": "show route protocol bgp", "is_correct": true}, {"id": "B", "text": "show bgp routes", "is_correct": false}, {"id": "C", "text": "show route bgp", "is_correct": false}, {"id": "D", "text": "show protocols bgp routes", "is_correct": false}]', '''show route protocol bgp'' displays BGP routes in the routing table. ''show bgp summary'' shows BGP peering status (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Operations', 8.0, '{"ru": "Какая команда показывает BGP-маршруты в таблице маршрутизации Junos (вариант 3)."}', '{"ru": [{"id": "A", "text": "show route protocol bgp"}, {"id": "B", "text": "show bgp routes"}, {"id": "C", "text": "show route bgp"}, {"id": "D", "text": "show protocols bgp routes"}]}', '206a407f337c4c2e_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('c96c5fc9-e4b6-4c85-aec3-13defbfdb34f', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of the ''load-balance'' per-packet action in Junos (variant 3).', '[{"id": "A", "text": "Distribute traffic across multiple equal-cost paths", "is_correct": true}, {"id": "B", "text": "Distribute traffic based on source IP", "is_correct": false}, {"id": "C", "text": "Create a static route for load sharing", "is_correct": false}, {"id": "D", "text": "Enable per-flow load balancing", "is_correct": false}]', '''load-balance per-packet'' enables per-packet load balancing across equal-cost multipath (ECMP) routes in the forwarding table (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '{"ru": "Какова цель action ''load-balance per-packet'' в Junos (вариант 3)."}', '{"ru": [{"id": "A", "text": "Distribute traffic across multiple equal-cost paths"}, {"id": "B", "text": "Distribute traffic based on source IP"}, {"id": "C", "text": "Create a static route for load sharing"}, {"id": "D", "text": "Enable per-flow load balancing"}]}', 'a062808030b1e49c_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('38c7085e-0d7e-47a6-ab1b-b08f054ca263', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP feature allows a route reflector to send routes to clients without modifying the NEXT_HOP?', '[{"id": "A", "text": "Route reflection", "is_correct": true}, {"id": "B", "text": "Confederation", "is_correct": false}, {"id": "C", "text": "Multiprotocol BGP", "is_correct": false}, {"id": "D", "text": "Add-path", "is_correct": false}]', 'Route reflectors forward routes to clients without modifying NEXT_HOP, AS_PATH, or LOCAL_PREF. They add cluster ID and originator ID.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '{"ru": "Какая функция BGP позволяет route reflector отправлять маршруты клиентам без изменения NEXT_HOP?"}', '{"ru": [{"id": "A", "text": "Route reflection"}, {"id": "B", "text": "Confederation"}, {"id": "C", "text": "Multiprotocol BGP"}, {"id": "D", "text": "Add-path"}]}', 'b50ad6c2275d3614_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('9dfa3251-7c6c-40fa-8c62-7a9d73cf4ec4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector design, what is the purpose of the CLUSTER_LIST attribute?', '[{"id": "A", "text": "Loop prevention among route reflectors", "is_correct": true}, {"id": "B", "text": "Selecting the best path", "is_correct": false}, {"id": "C", "text": "Influencing outbound traffic", "is_correct": false}, {"id": "D", "text": "Signaling MPLS labels", "is_correct": false}]', 'CLUSTER_LIST prevents routing loops between route reflectors. When a RR sees its own cluster ID in the CLUSTER_LIST, it ignores the route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Design', 12.0, '{"ru": "Какова цель атрибута CLUSTER_LIST в дизайне BGP route reflector?"}', '{"ru": [{"id": "A", "text": "Loop prevention among route reflectors"}, {"id": "B", "text": "Selecting the best path"}, {"id": "C", "text": "Influencing outbound traffic"}, {"id": "D", "text": "Signaling MPLS labels"}]}', 'a35aa6c14fa99990_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('46d6b31b-a7da-42b4-8040-57af5e35916a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which MPLS signaling protocol uses UDP for label distribution?', '[{"id": "A", "text": "LDP", "is_correct": true}, {"id": "B", "text": "RSVP-TE", "is_correct": false}, {"id": "C", "text": "MP-BGP", "is_correct": false}, {"id": "D", "text": "SR-MPLS", "is_correct": false}]', 'LDP (Label Distribution Protocol) uses UDP for discovery (hello messages on port 646) and TCP for session establishment and label exchange.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP', 12.0, '{"ru": "Какой протокол сигнализации MPLS использует UDP для распределения меток?"}', '{"ru": [{"id": "A", "text": "LDP"}, {"id": "B", "text": "RSVP-TE"}, {"id": "C", "text": "MP-BGP"}, {"id": "D", "text": "SR-MPLS"}]}', 'a51bea5b9bd6a52e_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('6a451bef-9bf5-4ca9-8e29-f8b498489d08', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct command to configure a VRF instance in Junos?', '[{"id": "A", "text": "set routing-instances CUSTOMER-1 instance-type vrf", "is_correct": true}, {"id": "B", "text": "set vrf CUSTOMER-1", "is_correct": false}, {"id": "C", "text": "set protocols vrf CUSTOMER-1", "is_correct": false}, {"id": "D", "text": "set network-instance CUSTOMER-1 type vrf", "is_correct": false}]', 'VRFs are configured under ''routing-instances'' with ''instance-type vrf''. Route distinguisher and VRF import/export targets are also configured there.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, '{"ru": "Какая команда для настройки VRF-инстанса в Junos?"}', '{"ru": [{"id": "A", "text": "set routing-instances CUSTOMER-1 instance-type vrf"}, {"id": "B", "text": "set vrf CUSTOMER-1"}, {"id": "C", "text": "set protocols vrf CUSTOMER-1"}, {"id": "D", "text": "set network-instance CUSTOMER-1 type vrf"}]}', '7a2a9787d86f922a_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('c00ef7c6-1819-46a3-99c7-06da08245231', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP/MPLS IP VPN, what information does the Route Distinguisher provide?', '[{"id": "A", "text": "Uniquely identifies a route from a specific VRF", "is_correct": true}, {"id": "B", "text": "Identifies the VPN target community", "is_correct": false}, {"id": "C", "text": "Specifies the MPLS label for the route", "is_correct": false}, {"id": "D", "text": "Defines the VRF export policy", "is_correct": false}]', 'RD makes a route unique across VPNs. Two VRFs can use overlapping IPs; RD + prefix = unique VPNv4 route.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, '{"ru": "Какую информацию предоставляет Route Distinguisher в BGP/MPLS IP VPN?"}', '{"ru": [{"id": "A", "text": "Uniquely identifies a route from a specific VRF"}, {"id": "B", "text": "Identifies the VPN target community"}, {"id": "C", "text": "Specifies the MPLS label for the route"}, {"id": "D", "text": "Defines the VRF export policy"}]}', '170b1c9b83cc1fe6_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('eba5a9ba-488a-44a0-96f2-ef36a600e9ef', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which statement about MPLS-TE FRR (Fast Reroute) is correct?', '[{"id": "A", "text": "FRR uses a pre-computed backup LSP to protect against link failures", "is_correct": true}, {"id": "B", "text": "FRR requires BGP to function", "is_correct": false}, {"id": "C", "text": "FRR is only available with LDP", "is_correct": false}, {"id": "D", "text": "FRR protects against node failures only", "is_correct": false}]', 'FRR pre-computes a backup LSP (bypass tunnel) that protects the primary LSP. Upon failure, traffic switches to the backup within 50ms.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS-TE', 14.0, '{"ru": "Какое утверждение о MPLS-TE FRR (Fast Reroute) верно?"}', '{"ru": [{"id": "A", "text": "FRR uses a pre-computed backup LSP to protect against link failures"}, {"id": "B", "text": "FRR requires BGP to function"}, {"id": "C", "text": "FRR is only available with LDP"}, {"id": "D", "text": "FRR protects against node failures only"}]}', '5c1d75877aa61f9c_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('53423a17-5b14-4148-b38f-5c2d1269800b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 3, 'understand', 'Which two MPLS applications typically use LDP for label distribution? (Select TWO)', '[{"id": "A", "text": "Layer 3 VPN (RFC 4364)", "is_correct": true}, {"id": "B", "text": "Layer 2 Circuit", "is_correct": true}, {"id": "C", "text": "MPLS-TE", "is_correct": false}, {"id": "D", "text": "RSVP", "is_correct": false}]', 'L3VPN and Layer 2 Circuit both use LDP for transport label distribution. MPLS-TE uses RSVP, and RSVP is a separate protocol.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Applications', 14.0, '{"ru": "Какие два приложения MPLS обычно используют LDP для распределения меток? (Выберите ДВА)"}', '{"ru": [{"id": "A", "text": "Layer 3 VPN (RFC 4364)"}, {"id": "B", "text": "Layer 2 Circuit"}, {"id": "C", "text": "MPLS-TE"}, {"id": "D", "text": "RSVP"}]}', '58e9be208f7f7ce0_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('ac0dc09d-fb42-4954-a716-48eb8b02cdbf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does the ''policy-options'' community ''target:100:1'' specify in Junos?', '[{"id": "A", "text": "Route target community for VPN: AS 100, local ID 1", "is_correct": true}, {"id": "B", "text": "BGP community 100:1", "is_correct": false}, {"id": "C", "text": "MSDP mesh group identifier", "is_correct": false}, {"id": "D", "text": "MPLS label range", "is_correct": false}]', 'Target communities follow format ''target:<ASN>:<local-assigned>''. Route targets control VRF import/export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'VPN Policy', 12.0, '{"ru": "Что означает community ''target:100:1'' в ''policy-options'' Junos?"}', '{"ru": [{"id": "A", "text": "Route target community for VPN: AS 100, local ID 1"}, {"id": "B", "text": "BGP community 100:1"}, {"id": "C", "text": "MSDP mesh group identifier"}, {"id": "D", "text": "MPLS label range"}]}', '65de9bd56d5b06f5_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('7f66a922-1fb4-44df-ac6d-4b5678be17f8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a route reflector hierarchy, what is a ''client-to-client reflection''?', '[{"id": "A", "text": "RR reflects routes between its clients by default", "is_correct": true}, {"id": "B", "text": "Clients must peer directly with each other", "is_correct": false}, {"id": "C", "text": "RR only reflects routes from non-clients", "is_correct": false}, {"id": "D", "text": "Client-to-client reflection is disabled by default", "is_correct": false}]', 'By default, a BGP route reflector reflects routes learned from one client to all other clients. This can be disabled with ''no-client-to-client-reflection''.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 14.0, '{"ru": "Что такое ''client-to-client reflection'' в иерархии route reflector?"}', '{"ru": [{"id": "A", "text": "RR reflects routes between its clients by default"}, {"id": "B", "text": "Clients must peer directly with each other"}, {"id": "C", "text": "RR only reflects routes from non-clients"}, {"id": "D", "text": "Client-to-client reflection is disabled by default"}]}', 'c79c9f155807726e_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('61d5fcf4-fe3a-4e06-a8ac-b9be32a31fb0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'Which command verifies LDP session status in Junos?', '[{"id": "A", "text": "show ldp session", "is_correct": true}, {"id": "B", "text": "show mpls ldp session", "is_correct": false}, {"id": "C", "text": "show ldp neighbor", "is_correct": false}, {"id": "D", "text": "show protocols ldp status", "is_correct": false}]', '''show ldp session'' displays LDP session state, neighbor address, and label advertisement mode. ''show ldp neighbor'' shows discovery state.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP Operations', 8.0, '{"ru": "Какая команда проверяет статус LDP-сессии в Junos?"}', '{"ru": [{"id": "A", "text": "show ldp session"}, {"id": "B", "text": "show mpls ldp session"}, {"id": "C", "text": "show ldp neighbor"}, {"id": "D", "text": "show protocols ldp status"}]}', 'ffd003303ff4dcd5_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('cb88f2b2-3e31-4f55-962a-9e134fa56a5e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP feature allows a route reflector to send routes to clients without modifying the NEXT_HOP (variant 2).', '[{"id": "A", "text": "Route reflection", "is_correct": true}, {"id": "B", "text": "Confederation", "is_correct": false}, {"id": "C", "text": "Multiprotocol BGP", "is_correct": false}, {"id": "D", "text": "Add-path", "is_correct": false}]', 'Route reflectors forward routes to clients without modifying NEXT_HOP, AS_PATH, or LOCAL_PREF. They add cluster ID and originator ID (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '{"ru": "Какая функция BGP позволяет route reflector отправлять маршруты клиентам без изменения NEXT_HOP (вариант 2)."}', '{"ru": [{"id": "A", "text": "Route reflection"}, {"id": "B", "text": "Confederation"}, {"id": "C", "text": "Multiprotocol BGP"}, {"id": "D", "text": "Add-path"}]}', '322d9d8ec82297cf_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('10d4d121-93c9-46d6-815a-631cde77d205', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector design, what is the purpose of the CLUSTER_LIST attribute (variant 2).', '[{"id": "A", "text": "Loop prevention among route reflectors", "is_correct": true}, {"id": "B", "text": "Selecting the best path", "is_correct": false}, {"id": "C", "text": "Influencing outbound traffic", "is_correct": false}, {"id": "D", "text": "Signaling MPLS labels", "is_correct": false}]', 'CLUSTER_LIST prevents routing loops between route reflectors. When a RR sees its own cluster ID in the CLUSTER_LIST, it ignores the route (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Design', 12.0, '{"ru": "Какова цель атрибута CLUSTER_LIST в дизайне BGP route reflector (вариант 2)."}', '{"ru": [{"id": "A", "text": "Loop prevention among route reflectors"}, {"id": "B", "text": "Selecting the best path"}, {"id": "C", "text": "Influencing outbound traffic"}, {"id": "D", "text": "Signaling MPLS labels"}]}', '91fc6c6d46fdb02f_gen_v2', true) ON CONFLICT (id) DO NOTHING;
