INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('ff6c00f2-701f-4f9e-b5d0-b86a7eefeec6', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which RSVP message is used to tear down an established LSP (variant 4).', '[{"id": "A", "text": "PathTear", "is_correct": true}, {"id": "B", "text": "ResvTear", "is_correct": false}, {"id": "C", "text": "PathErr", "is_correct": false}, {"id": "D", "text": "ResvErr", "is_correct": false}]', 'PathTear travels from ingress to egress tearing down the LSP. ResvTear travels upstream from egress to ingress (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/rsvp/"}', 'RSVP-TE', 14.0, '{"ru": "Какое сообщение RSVP используется для разрыва установленного LSP (вариант 4)."}', '{"ru": [{"id": "A", "text": "PathTear"}, {"id": "B", "text": "ResvTear"}, {"id": "C", "text": "PathErr"}, {"id": "D", "text": "ResvErr"}]}', '95086673bd1182a3_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('e46a9f75-0956-41be-afac-6ede5e661631', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'In the context of MPLS, what is PHP (variant 4).', '[{"id": "A", "text": "Penultimate Hop Popping — the second-to-last router removes the label", "is_correct": true}, {"id": "B", "text": "Path Hop Protocol — a signaling mechanism", "is_correct": false}, {"id": "C", "text": "Per-Hop Policing — QoS enforcement", "is_correct": false}, {"id": "D", "text": "Provider Hub Point — a central aggregation router", "is_correct": false}]', 'PHP is when the penultimate hop router pops the MPLS label before forwarding the packet to the egress router. This reduces the load on the egress router (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 12.0, '{"ru": "Что такое PHP в контексте MPLS (вариант 4)."}', '{"ru": [{"id": "A", "text": "Penultimate Hop Popping — the second-to-last router removes the label"}, {"id": "B", "text": "Path Hop Protocol — a signaling mechanism"}, {"id": "C", "text": "Per-Hop Policing — QoS enforcement"}, {"id": "D", "text": "Provider Hub Point — a central aggregation router"}]}', 'ac671218fac25870_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('4b5da267-1fff-4f85-93ea-35f3a484d0e4', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos (variant 5).', '[{"id": "A", "text": "16 through 1023", "is_correct": true}, {"id": "B", "text": "0 through 15", "is_correct": false}, {"id": "C", "text": "1024 through 65535", "is_correct": false}, {"id": "D", "text": "1 through 1000", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, '{"ru": "Каков диапазон динамических MPLS-меток по умолчанию в Junos (вариант 5)."}', '{"ru": [{"id": "A", "text": "16 through 1023"}, {"id": "B", "text": "0 through 15"}, {"id": "C", "text": "1024 through 65535"}, {"id": "D", "text": "1 through 1000"}]}', 'f3c95200544493f6_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('cebe906f-a801-4734-805e-2ccb8dd77b3f', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos (variant 5).', '[{"id": "A", "text": "show mpls lsp", "is_correct": true}, {"id": "B", "text": "show mpls path", "is_correct": false}, {"id": "C", "text": "show rsvp lsp", "is_correct": false}, {"id": "D", "text": "show ldp lsp", "is_correct": false}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, '{"ru": "Какая команда показывает информацию о LSP в Junos (вариант 5)."}', '{"ru": [{"id": "A", "text": "show mpls lsp"}, {"id": "B", "text": "show mpls path"}, {"id": "C", "text": "show rsvp lsp"}, {"id": "D", "text": "show ldp lsp"}]}', '5e510183593bbf2a_gen_v2', true) ON CONFLICT (id) DO NOTHING;
