INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('dce04d5b-e27f-4527-b22c-c779a58f8220', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'In the context of MPLS, what is PHP (variant 5).', '[{"id": "A", "text": "Penultimate Hop Popping — the second-to-last router removes the label", "is_correct": true}, {"id": "B", "text": "Path Hop Protocol — a signaling mechanism", "is_correct": false}, {"id": "C", "text": "Per-Hop Policing — QoS enforcement", "is_correct": false}, {"id": "D", "text": "Provider Hub Point — a central aggregation router", "is_correct": false}]', 'PHP is when the penultimate hop router pops the MPLS label before forwarding the packet to the egress router. This reduces the load on the egress router (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 12.0, '{"ru": "Что такое PHP в контексте MPLS (вариант 5)."}', '{"ru": [{"id": "A", "text": "Penultimate Hop Popping — the second-to-last router removes the label"}, {"id": "B", "text": "Path Hop Protocol — a signaling mechanism"}, {"id": "C", "text": "Per-Hop Policing — QoS enforcement"}, {"id": "D", "text": "Provider Hub Point — a central aggregation router"}]}', '4ca8b914eef43e1b_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('89c7d481-305b-4876-9094-13dc0108221f', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which Junos feature provides application-aware security policies?', '[{"id": "A", "text": "Application Firewall (AppFW)", "is_correct": true}, {"id": "B", "text": "Stateful firewall filtering", "is_correct": false}, {"id": "C", "text": "Simple packet filter", "is_correct": false}, {"id": "D", "text": "MAC-based filtering", "is_correct": false}]', 'AppFW (Application Firewall) identifies applications using Juniper''s Application Signature database, enabling application-aware security policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/appfw/"}', 'Security Policies', 14.0, '{"ru": "Какая функция Junos обеспечивает контекстные политики безопасности на уровне приложений?"}', '{"ru": [{"id": "A", "text": "Application Firewall (AppFW)"}, {"id": "B", "text": "Stateful firewall filtering"}, {"id": "C", "text": "Simple packet filter"}, {"id": "D", "text": "MAC-based filtering"}]}', '269508a4dfbcb05d_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('8414772f-f379-4e44-a730-1977b280b1a1', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is the default action for a Junos security policy if no match is found?', '[{"id": "A", "text": "Deny (all traffic not matching a policy is dropped)", "is_correct": true}, {"id": "B", "text": "Permit (all traffic is allowed)", "is_correct": false}, {"id": "C", "text": "Reject with ICMP unreachable", "is_correct": false}, {"id": "D", "text": "Log and permit", "is_correct": false}]', 'Junos uses an implicit deny-all policy. Traffic not matching any security policy is silently dropped. A ''default-permit'' policy can be explicitly configured.', '{"https://www.juniper.net/documentation/us/en/software/junos/security-policies/"}', 'Security Policies', 14.0, '{"ru": "Какое действие по умолчанию в Junos security policy, если совпадение не найдено?"}', '{"ru": [{"id": "A", "text": "Deny (all traffic not matching a policy is dropped)"}, {"id": "B", "text": "Permit (all traffic is allowed)"}, {"id": "C", "text": "Reject with ICMP unreachable"}, {"id": "D", "text": "Log and permit"}]}', '89d73feedce9e800_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('beb66681-20e6-4be7-8850-5665c081f318', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which IPsec mode encrypts the entire IP packet, including the original header?', '[{"id": "A", "text": "Tunnel mode", "is_correct": true}, {"id": "B", "text": "Transport mode", "is_correct": false}, {"id": "C", "text": "AH mode", "is_correct": false}, {"id": "D", "text": "ESP mode", "is_correct": false}]', 'Tunnel mode encrypts the entire original IP packet and adds a new IP header. Transport mode only encrypts the payload.', '{"https://www.juniper.net/documentation/us/en/software/junos/ipsec/"}', 'IPsec VPN', 14.0, '{"ru": "Какой режим IPsec шифрует весь IP-пакет, включая исходный заголовок?"}', '{"ru": [{"id": "A", "text": "Tunnel mode"}, {"id": "B", "text": "Transport mode"}, {"id": "C", "text": "AH mode"}, {"id": "D", "text": "ESP mode"}]}', 'd21311edb6ad4874_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('1e3d1106-add5-435a-a25c-f362df6d140c', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is a security zone in SRX?', '[{"id": "A", "text": "A logical grouping of interfaces to which security policies are applied", "is_correct": true}, {"id": "B", "text": "A physical security domain on the device", "is_correct": false}, {"id": "C", "text": "A routing instance for security traffic", "is_correct": false}, {"id": "D", "text": "A VLAN segment for guest networks", "is_correct": false}]', 'A security zone is a logical grouping of one or more interfaces. Security policies are applied between zones, controlling traffic from source to destination zones.', '{"https://www.juniper.net/documentation/us/en/software/junos/security-zones/"}', 'Security Zones', 14.0, '{"ru": "Что такое security zone в SRX?"}', '{"ru": [{"id": "A", "text": "A logical grouping of interfaces to which security policies are applied"}, {"id": "B", "text": "A physical security domain on the device"}, {"id": "C", "text": "A routing instance for security traffic"}, {"id": "D", "text": "A VLAN segment for guest networks"}]}', '2fd339e8d2957e36_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('03622b1d-4197-4198-8460-7f28b30de131', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'apply', 'Which Junos command creates a NAT source pool?', '[{"id": "A", "text": "set security nat source pool POOL1 address 192.168.1.100/32", "is_correct": true}, {"id": "B", "text": "set nat source pool POOL1 range 192.168.1.100", "is_correct": false}, {"id": "C", "text": "set security source-nat pool POOL1 192.168.1.100", "is_correct": false}, {"id": "D", "text": "set services nat pool POOL1 address 192.168.1.100", "is_correct": false}]', 'Source NAT pools are configured under ''security nat source pool <name>''. The pool defines the translated source IP addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/nat/"}', 'NAT', 14.0, '{"ru": "Какая команда Junos создаёт NAT source pool?"}', '{"ru": [{"id": "A", "text": "set security nat source pool POOL1 address 192.168.1.100/32"}, {"id": "B", "text": "set nat source pool POOL1 range 192.168.1.100"}, {"id": "C", "text": "set security source-nat pool POOL1 192.168.1.100"}, {"id": "D", "text": "set services nat pool POOL1 address 192.168.1.100"}]}', '65ed72487067080a_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('a1155db2-2421-4ada-9cc8-dd2797b6082e', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which Junos feature provides application-aware security policies (variant 2).', '[{"id": "A", "text": "Application Firewall (AppFW)", "is_correct": true}, {"id": "B", "text": "Stateful firewall filtering", "is_correct": false}, {"id": "C", "text": "Simple packet filter", "is_correct": false}, {"id": "D", "text": "MAC-based filtering", "is_correct": false}]', 'AppFW (Application Firewall) identifies applications using Juniper''s Application Signature database, enabling application-aware security policies (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/appfw/"}', 'Security Policies', 14.0, '{"ru": "Какая функция Junos обеспечивает контекстные политики безопасности на уровне приложений (вариант 2)."}', '{"ru": [{"id": "A", "text": "Application Firewall (AppFW)"}, {"id": "B", "text": "Stateful firewall filtering"}, {"id": "C", "text": "Simple packet filter"}, {"id": "D", "text": "MAC-based filtering"}]}', '4994a287c62d0736_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('ec329630-cbd1-48ab-89ea-f260295c1085', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is the default action for a Junos security policy if no match is found (variant 2).', '[{"id": "A", "text": "Deny (all traffic not matching a policy is dropped)", "is_correct": true}, {"id": "B", "text": "Permit (all traffic is allowed)", "is_correct": false}, {"id": "C", "text": "Reject with ICMP unreachable", "is_correct": false}, {"id": "D", "text": "Log and permit", "is_correct": false}]', 'Junos uses an implicit deny-all policy. Traffic not matching any security policy is silently dropped. A ''default-permit'' policy can be explicitly configured (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/security-policies/"}', 'Security Policies', 14.0, '{"ru": "Какое действие по умолчанию в Junos security policy, если совпадение не найдено (вариант 2)."}', '{"ru": [{"id": "A", "text": "Deny (all traffic not matching a policy is dropped)"}, {"id": "B", "text": "Permit (all traffic is allowed)"}, {"id": "C", "text": "Reject with ICMP unreachable"}, {"id": "D", "text": "Log and permit"}]}', 'ef46b776966273c3_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('bdb41835-cb8c-4317-ba37-a7ee747c2f05', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which IPsec mode encrypts the entire IP packet, including the original header (variant 2).', '[{"id": "A", "text": "Tunnel mode", "is_correct": true}, {"id": "B", "text": "Transport mode", "is_correct": false}, {"id": "C", "text": "AH mode", "is_correct": false}, {"id": "D", "text": "ESP mode", "is_correct": false}]', 'Tunnel mode encrypts the entire original IP packet and adds a new IP header. Transport mode only encrypts the payload (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/ipsec/"}', 'IPsec VPN', 14.0, '{"ru": "Какой режим IPsec шифрует весь IP-пакет, включая исходный заголовок (вариант 2)."}', '{"ru": [{"id": "A", "text": "Tunnel mode"}, {"id": "B", "text": "Transport mode"}, {"id": "C", "text": "AH mode"}, {"id": "D", "text": "ESP mode"}]}', '217881720d1d2b05_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('ce921bf1-b25c-4a01-aafe-a21618e0b343', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is a security zone in SRX (variant 2).', '[{"id": "A", "text": "A logical grouping of interfaces to which security policies are applied", "is_correct": true}, {"id": "B", "text": "A physical security domain on the device", "is_correct": false}, {"id": "C", "text": "A routing instance for security traffic", "is_correct": false}, {"id": "D", "text": "A VLAN segment for guest networks", "is_correct": false}]', 'A security zone is a logical grouping of one or more interfaces. Security policies are applied between zones, controlling traffic from source to destination zones (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/security-zones/"}', 'Security Zones', 14.0, '{"ru": "Что такое security zone в SRX (вариант 2)."}', '{"ru": [{"id": "A", "text": "A logical grouping of interfaces to which security policies are applied"}, {"id": "B", "text": "A physical security domain on the device"}, {"id": "C", "text": "A routing instance for security traffic"}, {"id": "D", "text": "A VLAN segment for guest networks"}]}', 'ed6f0de5bea4d517_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('66904f5e-f445-4a79-89a7-965c990c645e', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'apply', 'Which Junos command creates a NAT source pool (variant 2).', '[{"id": "A", "text": "set security nat source pool POOL1 address 192.168.1.100/32", "is_correct": true}, {"id": "B", "text": "set nat source pool POOL1 range 192.168.1.100", "is_correct": false}, {"id": "C", "text": "set security source-nat pool POOL1 192.168.1.100", "is_correct": false}, {"id": "D", "text": "set services nat pool POOL1 address 192.168.1.100", "is_correct": false}]', 'Source NAT pools are configured under ''security nat source pool <name>''. The pool defines the translated source IP addresses (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/nat/"}', 'NAT', 14.0, '{"ru": "Какая команда Junos создаёт NAT source pool (вариант 2)."}', '{"ru": [{"id": "A", "text": "set security nat source pool POOL1 address 192.168.1.100/32"}, {"id": "B", "text": "set nat source pool POOL1 range 192.168.1.100"}, {"id": "C", "text": "set security source-nat pool POOL1 192.168.1.100"}, {"id": "D", "text": "set services nat pool POOL1 address 192.168.1.100"}]}', '8954ded91182e238_gen_v2', true) ON CONFLICT (id) DO NOTHING;
