INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('3e6d3e7c-fed1-4056-997d-4df8b8a30396', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is a security zone in SRX (variant 5).', '[{"id": "A", "text": "A logical grouping of interfaces to which security policies are applied", "is_correct": true}, {"id": "B", "text": "A physical security domain on the device", "is_correct": false}, {"id": "C", "text": "A routing instance for security traffic", "is_correct": false}, {"id": "D", "text": "A VLAN segment for guest networks", "is_correct": false}]', 'A security zone is a logical grouping of one or more interfaces. Security policies are applied between zones, controlling traffic from source to destination zones (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/security-zones/"}', 'Security Zones', 14.0, '{"ru": "Что такое security zone в SRX (вариант 5)."}', '{"ru": [{"id": "A", "text": "A logical grouping of interfaces to which security policies are applied"}, {"id": "B", "text": "A physical security domain on the device"}, {"id": "C", "text": "A routing instance for security traffic"}, {"id": "D", "text": "A VLAN segment for guest networks"}]}', '80f30232680f71f4_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('7c8963cc-67d7-4b4e-8784-ff53b4a97724', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'apply', 'Which Junos command creates a NAT source pool (variant 5).', '[{"id": "A", "text": "set security nat source pool POOL1 address 192.168.1.100/32", "is_correct": true}, {"id": "B", "text": "set nat source pool POOL1 range 192.168.1.100", "is_correct": false}, {"id": "C", "text": "set security source-nat pool POOL1 192.168.1.100", "is_correct": false}, {"id": "D", "text": "set services nat pool POOL1 address 192.168.1.100", "is_correct": false}]', 'Source NAT pools are configured under ''security nat source pool <name>''. The pool defines the translated source IP addresses (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/nat/"}', 'NAT', 14.0, '{"ru": "Какая команда Junos создаёт NAT source pool (вариант 5)."}', '{"ru": [{"id": "A", "text": "set security nat source pool POOL1 address 192.168.1.100/32"}, {"id": "B", "text": "set nat source pool POOL1 range 192.168.1.100"}, {"id": "C", "text": "set security source-nat pool POOL1 192.168.1.100"}, {"id": "D", "text": "set services nat pool POOL1 address 192.168.1.100"}]}', '4a703d3545ccfe28_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('0ffb970f-0e7d-40ac-9678-59b060f75944', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which Junos feature provides application-aware security policies (variant 6).', '[{"id": "A", "text": "Application Firewall (AppFW)", "is_correct": true}, {"id": "B", "text": "Stateful firewall filtering", "is_correct": false}, {"id": "C", "text": "Simple packet filter", "is_correct": false}, {"id": "D", "text": "MAC-based filtering", "is_correct": false}]', 'AppFW (Application Firewall) identifies applications using Juniper''s Application Signature database, enabling application-aware security policies (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/appfw/"}', 'Security Policies', 14.0, '{"ru": "Какая функция Junos обеспечивает контекстные политики безопасности на уровне приложений (вариант 6)."}', '{"ru": [{"id": "A", "text": "Application Firewall (AppFW)"}, {"id": "B", "text": "Stateful firewall filtering"}, {"id": "C", "text": "Simple packet filter"}, {"id": "D", "text": "MAC-based filtering"}]}', '1fc65733a1303c67_gen_v2', true) ON CONFLICT (id) DO NOTHING;
