INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('5f9009fa-0a01-4550-a742-3e2a8ad6f8ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which IPv6 address type is equivalent to a private IPv4 address?', '[{"id": "A", "text": "Unique Local (fc00::/7)", "is_correct": true}, {"id": "B", "text": "Link-Local (fe80::/10)", "is_correct": false}, {"id": "C", "text": "Global Unicast (2000::/3)", "is_correct": false}, {"id": "D", "text": "Multicast (ff00::/8)", "is_correct": false}]', 'Unique Local Unicast addresses (fc00::/7) are the IPv6 equivalent of RFC 1918 private addresses. They are not globally routable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IPv6', 12.0, '{"ru": "Какой тип IPv6-адреса эквивалентен частному IPv4-адресу?"}', '{"ru": [{"id": "A", "text": "Unique Local (fc00::/7)"}, {"id": "B", "text": "Link-Local (fe80::/10)"}, {"id": "C", "text": "Global Unicast (2000::/3)"}, {"id": "D", "text": "Multicast (ff00::/8)"}]}', 'd8a9ec03e976c084_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('f8bf43d2-2118-4aad-92e3-7d41428288eb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the ''spanning-tree portfast'' command on a Cisco switch?', '[{"id": "A", "text": "Bypasses the listening and learning states for access ports", "is_correct": true}, {"id": "B", "text": "Enables rapid STP on the port", "is_correct": false}, {"id": "C", "text": "Disables STP on the port", "is_correct": false}, {"id": "D", "text": "Configures the port as a trunk", "is_correct": false}]', 'PortFast immediately transitions a port from blocking to forwarding state, bypassing listening and learning. Used only on access ports connected to end hosts.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'STP', 12.0, '{"ru": "Какова цель команды ''spanning-tree portfast'' на Cisco-коммутаторе?"}', '{"ru": [{"id": "A", "text": "Bypasses the listening and learning states for access ports"}, {"id": "B", "text": "Enables rapid STP on the port"}, {"id": "C", "text": "Disables STP on the port"}, {"id": "D", "text": "Configures the port as a trunk"}]}', '2903e45cdf395da8_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('4b582fa4-94d3-4936-a090-3222ea0c1cf0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is considered link-state?', '[{"id": "A", "text": "OSPF", "is_correct": true}, {"id": "B", "text": "RIP", "is_correct": false}, {"id": "C", "text": "EIGRP", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'OSPF (Open Shortest Path First) is a link-state routing protocol. It maintains a complete view of the network topology using LSAs.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'Routing Protocols', 12.0, '{"ru": "Какой протокол маршрутизации является link-state?"}', '{"ru": [{"id": "A", "text": "OSPF"}, {"id": "B", "text": "RIP"}, {"id": "C", "text": "EIGRP"}, {"id": "D", "text": "BGP"}]}', 'e15fdfe68a1168f0_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('8ef32bba-e191-4188-98f2-2b3fc0a956cc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the administrative distance of External EIGRP?', '[{"id": "A", "text": "170", "is_correct": true}, {"id": "B", "text": "20", "is_correct": false}, {"id": "C", "text": "90", "is_correct": false}, {"id": "D", "text": "110", "is_correct": false}]', 'External EIGRP routes (redistributed) have AD 170. Internal EIGRP has AD 90.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'Routing Fundamentals', 12.0, '{"ru": "Каково administrative distance внешнего EIGRP?"}', '{"ru": [{"id": "A", "text": "170"}, {"id": "B", "text": "20"}, {"id": "C", "text": "90"}, {"id": "D", "text": "110"}]}', '530d3ff2ba189adc_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('a9812bbe-9371-4b43-bfb2-3d0a35412d67', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which IPv6 address type is equivalent to a private IPv4 address (variant 2).', '[{"id": "A", "text": "Unique Local (fc00::/7)", "is_correct": true}, {"id": "B", "text": "Link-Local (fe80::/10)", "is_correct": false}, {"id": "C", "text": "Global Unicast (2000::/3)", "is_correct": false}, {"id": "D", "text": "Multicast (ff00::/8)", "is_correct": false}]', 'Unique Local Unicast addresses (fc00::/7) are the IPv6 equivalent of RFC 1918 private addresses. They are not globally routable (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IPv6', 12.0, '{"ru": "Какой тип IPv6-адреса эквивалентен частному IPv4-адресу (вариант 2)."}', '{"ru": [{"id": "A", "text": "Unique Local (fc00::/7)"}, {"id": "B", "text": "Link-Local (fe80::/10)"}, {"id": "C", "text": "Global Unicast (2000::/3)"}, {"id": "D", "text": "Multicast (ff00::/8)"}]}', '3d452ef12b05112c_gen_v2', true) ON CONFLICT (id) DO NOTHING;
