SELECT gen_random_uuid(), q.id, 1, '[{"type": "tldr", "title": "TL;DR", "content": "AS_PATH is the primary loop prevention mechanism in BGP. When a router sees its own AS in the AS_PATH, it rejects the route."}, {"type": "tldr", "title": "Коротко", "content": "AS_PATH — основной механизм предотвращения петель в BGP. Когда маршрутизатор видит свою AS в AS_PATH, он отвергает маршрут.", "lang": "ru"}, {"type": "distractor_breakdown", "title": "Разбор вариантов", "content": "**B** - Неверно.\n\n**C** - Неверно.\n\n**D** - Неверно."}]', 'AS_PATH — основной механизм предотвращения петель в BGP. Когда маршрутизатор видит свою AS в AS_PATH, он отвергает маршрут.', NOW()
FROM questions q WHERE q.content_hash = 'f21f0de1cccb59b2_gen_v2' AND NOT EXISTS (SELECT 1 FROM explanations e WHERE e.question_id = q.id);
