SELECT gen_random_uuid(), q.id, 1, '[{"type": "tldr", "title": "TL;DR", "content": "OSPF external routes (Type 5) have a default preference of 150 in Junos. OSPF internal routes have preference 10."}, {"type": "tldr", "title": "Коротко", "content": "Внешние маршруты OSPF (Type 5) имеют preference 150 в Junos. Внутренние маршруты OSPF — 10.", "lang": "ru"}, {"type": "distractor_breakdown", "title": "Разбор вариантов", "content": "**B** - Неверно.\n\n**C** - Неверно.\n\n**D** - Неверно."}]', 'Внешние маршруты OSPF (Type 5) имеют preference 150 в Junos. Внутренние маршруты OSPF — 10.', NOW()
