SELECT gen_random_uuid(), q.id, 1, '[{"type": "tldr", "title": "TL;DR", "content": "OSPF external routes (Type 5) have a default preference of 150 in Junos. OSPF internal routes have preference 10 (Variant 3)."}, {"type": "tldr", "title": "Коротко", "content": "Внешние маршруты OSPF (Type 5) имеют preference 150 в Junos. Внутренние маршруты OSPF — 10 (Вариант 3).", "lang": "ru"}, {"type": "distractor_breakdown", "title": "Разбор вариантов", "content": "**B** - Неверно.\n\n**C** - Неверно.\n\n**D** - Неверно."}]', 'Внешние маршруты OSPF (Type 5) имеют preference 150 в Junos. Внутренние маршруты OSPF — 10 (Вариант 3).', NOW()
FROM questions q WHERE q.content_hash = 'b079454301feba1f_gen_v2' AND NOT EXISTS (SELECT 1 FROM explanations e WHERE e.question_id = q.id);
INSERT INTO explanations (id, question_id, version, sections, summary, created_at)
SELECT gen_random_uuid(), q.id, 1, '[{"type": "tldr", "title": "TL;DR", "content": "Area 0 is the backbone; all non-backbone areas must connect to it. Stub areas cannot contain ASBRs. NSSA uses Type 7 LSAs (Variant 3)."}, {"type": "tldr", "title": "Коротко", "content": "Area 0 — магистральная зона; все остальные зоны должны подключаться к ней. Stub-зоны не могут содержать ASBR. NSSA использует Type 7 LSA (Вариант 3).", "lang": "ru"}]', 'Area 0 — магистральная зона; все остальные зоны должны подключаться к ней. Stub-зоны не могут содержать ASBR. NSSA использует Type 7 LSA (Вариант 3).', NOW()
