INSERT INTO explanations (id, question_id, version, sections, summary, created_at)
SELECT gen_random_uuid(), q.id, 1, '[{"type": "tldr", "title": "TL;DR", "content": "PathTear travels from ingress to egress tearing down the LSP. ResvTear travels upstream from egress to ingress."}, {"type": "tldr", "title": "Коротко", "content": "PathTear идёт от ingress к egress, разрывая LSP. ResvTear идёт в обратном направлении.", "lang": "ru"}, {"type": "distractor_breakdown", "title": "Разбор вариантов", "content": "**B** - Неверно.\n\n**C** - Неверно.\n\n**D** - Неверно."}]', 'PathTear идёт от ingress к egress, разрывая LSP. ResvTear идёт в обратном направлении.', NOW()
